-- Create "timetable_generation_jobs" table
CREATE TABLE "timetable_generation_jobs" ("id" uuid NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now(), "status" character varying NOT NULL DEFAULT 'queued', "max_seconds" bigint NOT NULL DEFAULT 60, "options" jsonb NULL, "started_at" timestamptz NULL, "finished_at" timestamptz NULL, "slots_written" bigint NOT NULL DEFAULT 0, "wall_time_ms" bigint NOT NULL DEFAULT 0, "solver_status" character varying NULL, "verdict" character varying NULL, "objective" double precision NULL, "failure_reason" character varying NULL, "detail" character varying NULL, "core_keys" jsonb NULL, "warnings" jsonb NULL, "soft_violations" jsonb NULL, "timetable_id" uuid NOT NULL, "requested_by" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "timetable_generation_jobs_persons_requester" FOREIGN KEY ("requested_by") REFERENCES "persons" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "timetable_generation_jobs_timetables_generation_jobs" FOREIGN KEY ("timetable_id") REFERENCES "timetables" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "timetable_generation_jobs_failure_named" CHECK (((status)::text <> 'failed'::text) OR (failure_reason IS NOT NULL)), CONSTRAINT "timetable_generation_jobs_success_is_silent" CHECK (((status)::text = 'failed'::text) OR (failure_reason IS NULL)), CONSTRAINT "timetable_generation_jobs_terminal_finished" CHECK (((status)::text = ANY ((ARRAY['queued'::character varying, 'running'::character varying])::text[])) OR (finished_at IS NOT NULL)));
-- Create index "timetablegenerationjob_status_created_at" to table: "timetable_generation_jobs"
CREATE INDEX "timetablegenerationjob_status_created_at" ON "timetable_generation_jobs" ("status", "created_at");
-- Create index "timetablegenerationjob_timetable_id" to table: "timetable_generation_jobs"
CREATE UNIQUE INDEX "timetablegenerationjob_timetable_id" ON "timetable_generation_jobs" ("timetable_id") WHERE ((status)::text = ANY ((ARRAY['queued'::character varying, 'running'::character varying])::text[]));
-- Create index "timetablegenerationjob_timetable_id_created_at" to table: "timetable_generation_jobs"
CREATE INDEX "timetablegenerationjob_timetable_id_created_at" ON "timetable_generation_jobs" ("timetable_id", "created_at");
